<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '@/api'
import { dateTime } from '@/utils/format'
const active=ref('basic');const loading=ref(true);const settings=reactive({site_name:'校园集市',audit_required:'true',max_product_images:'9',service_fee_rate:'0'});const logs=ref({items:[],total:0})
const load=async()=>{loading.value=true;try{const data=await api.get('/admin/settings');Object.keys(settings).forEach(k=>{if(data[k])settings[k]=data[k].value});logs.value=await api.get('/admin/audit-logs')}finally{loading.value=false}}
const save=async()=>{await api.put('/admin/settings',{values:{...settings}});ElMessage.success('系统设置已保存')}
onMounted(load)
</script>
<template><div v-loading="loading" class="settings-layout"><aside class="settings-menu"><button v-for="item in [{v:'basic',l:'基础设置',i:'Setting'},{v:'trade',l:'交易设置',i:'Tickets'},{v:'audit',l:'审核策略',i:'View'},{v:'logs',l:'操作日志',i:'Document'}]" :key="item.v" :class="{active:active===item.v}" @click="active=item.v"><el-icon><component :is="item.i"/></el-icon>{{item.l}}</button></aside><section class="admin-card settings-content"><template v-if="active==='basic'"><div class="admin-card-header"><div><h2>基础设置</h2><p>设置平台名称和基础展示信息</p></div></div><el-form label-position="top" class="setting-form"><el-form-item label="平台名称"><el-input v-model="settings.site_name"/></el-form-item><el-form-item label="平台简介"><el-input value="可信、便捷的校园二手商品交易平台" type="textarea" :rows="3"/></el-form-item><el-form-item label="客服时间"><el-input value="工作日 09:00-18:00"/></el-form-item><el-form-item label="平台状态"><el-switch :model-value="true" active-text="正常运营"/></el-form-item><el-button type="success" @click="save">保存设置</el-button></el-form></template><template v-else-if="active==='trade'"><div class="admin-card-header"><div><h2>交易设置</h2><p>配置订单与平台服务规则</p></div></div><el-form label-position="top" class="setting-form"><el-form-item label="平台服务费比例"><el-input v-model="settings.service_fee_rate"><template #append>%</template></el-input><small>校园公益平台建议保持为 0</small></el-form-item><el-form-item label="未付款订单自动取消"><el-input-number :model-value="30" :min="5"/><span class="unit">分钟</span></el-form-item><el-form-item label="交易完成后评价期限"><el-input-number :model-value="7" :min="1"/><span class="unit">天</span></el-form-item><el-button type="success" @click="save">保存设置</el-button></el-form></template><template v-else-if="active==='audit'"><div class="admin-card-header"><div><h2>审核策略</h2><p>管理商品发布和内容安全规则</p></div></div><div class="policy-list"><div><div><strong>新商品发布审核</strong><p>开启后，普通用户发布或修改商品需管理员审核</p></div><el-switch v-model="settings.audit_required" active-value="true" inactive-value="false"/></div><div><div><strong>单个商品最大图片数</strong><p>控制发布表单最多可上传的图片数量</p></div><el-input-number v-model="settings.max_product_images" :min="1" :max="20"/></div><div><div><strong>敏感词自动拦截</strong><p>命中高风险词库的内容将直接进入人工复核</p></div><el-switch :model-value="true"/></div><div><div><strong>高价值商品重点审核</strong><p>价格超过 3000 元的商品自动标记高风险</p></div><el-switch :model-value="true"/></div></div><el-button type="success" @click="save">保存策略</el-button></template><template v-else><div class="admin-card-header"><div><h2>操作日志</h2><p>记录管理员对平台数据的重要变更</p></div></div><el-table :data="logs.items"><el-table-column label="操作人" prop="operator.nickname"/><el-table-column label="操作" prop="action"/><el-table-column label="目标"><template #default="{row}">{{row.target_type}} #{{row.target_id}}</template></el-table-column><el-table-column label="详情" min-width="260" show-overflow-tooltip prop="detail"/><el-table-column label="IP" prop="ip_address"/><el-table-column label="时间" width="170"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column></el-table></template></section></div></template>
<style scoped>.settings-layout{display:grid;grid-template-columns:210px 1fr;gap:18px;align-items:start}.settings-menu{padding:9px;border:1px solid #e0e6e0;border-radius:10px;background:#fff}.settings-menu button{width:100%;height:44px;display:flex;align-items:center;gap:9px;padding:0 12px;border:0;border-radius:7px;background:transparent;color:#627068}.settings-menu button.active{background:#eaf3e7;color:#26743b;font-weight:700}.settings-content{min-height:620px}.admin-card-header{padding-bottom:17px;border-bottom:1px solid #e3e8e3}.admin-card-header p{margin-top:5px;color:#8c958e;font-size:11px}.setting-form{width:620px;margin-top:24px}.setting-form small{display:block;margin-top:6px;color:#929a94}.unit{margin-left:8px;color:#738078}.policy-list{margin:15px 0 24px}.policy-list>div{min-height:74px;display:flex;align-items:center;justify-content:space-between;padding:12px 4px;border-bottom:1px solid #e5e9e4}.policy-list p{margin-top:5px;color:#89928c;font-size:12px}</style>

